// Pick the newest real post from the Apify results and attach it to this lead.
const lead = $('Prepare Lead Fields').first().json;
const rows = $input.all().map((item) => item.json);

// Some actors return one item per post, others wrap them as { data: { posts: [...] } }.
const posts = rows.flatMap((row) => row?.data?.posts ?? [row]);

// Keep real posts only: enough text, and not a plain repost.
const goodPosts = posts.filter(
  (post) =>
    typeof post?.text === 'string' &&
    post.text.trim().length > 50 &&
    post.post_type !== 'repost'
);

let recentPost = '';
if (goodPosts.length > 0) {
  const latest = goodPosts[0];
  const text = latest.text.trim();
  const excerpt = text.length > 400 ? text.substring(0, 400) + '...' : text;
  // Apify adds "• Visible to anyone..." after the time. Keep only the time.
  const when = String(latest.posted_at?.relative || 'recently').split('•')[0].trim();
  recentPost = `${excerpt} (posted ${when})`;
}

// If the sheet has a bare domain like acme.com, add https:// so the request works.
let website = String(lead.company_website || '').trim();
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;

return [{ json: { ...lead, company_website: website, recent_post: recentPost } }];

// Put everything the AI needs for this lead into one item.
const lead = $('Pick Latest Post').first().json;
const websiteSummary = $input.first().json.text || '';

return [
  {
    json: {
      email: lead.email,
      name: lead.first_name,
      company: lead.company_name,
      website_summary: websiteSummary,
      recent_post: lead.recent_post || '',
    },
  },
];

// Last quality check. Anything robotic, salesy or generic becomes SKIP.
const lead = $('Build Context').first().json;
const raw = $input.first().json.text;

const result = (icebreaker, status, reason = '') => [
  { json: { email: lead.email, icebreaker, status, reason } },
];

// The AI call failed or came back empty. We keep the lead as NOT processed so it retries next run.
if (typeof raw !== 'string' || raw.trim() === '') {
  return result('', 'error', 'no_ai_output');
}

let icebreaker = raw.trim();

// Remove quotes wrapped around the whole line.
if (
  (icebreaker.startsWith('"') && icebreaker.endsWith('"')) ||
  (icebreaker.startsWith("'") && icebreaker.endsWith("'"))
) {
  icebreaker = icebreaker.slice(1, -1).trim();
}

// The AI decided there was nothing good to write about.
if (icebreaker.toUpperCase() === 'SKIP') {
  return result('SKIP', 'skipped', 'no_good_detail');
}

// Lowercase, and straighten curly apostrophes so phrase matching is reliable.
const lower = icebreaker.toLowerCase().replace(/[‘’]/g, "'");

// Rule 1: a reference to a post must say LinkedIn.
if ((lower.includes('your post') || lower.includes('saw your post')) && !lower.includes('linkedin')) {
  return result('SKIP', 'skipped', 'no_linkedin');
}

// Rule 2: no dashes used as punctuation.
if (/\s[-–—]\s/.test(icebreaker) || /[–—]/.test(icebreaker)) {
  return result('SKIP', 'skipped', 'dash');
}

// Rule 3: banned phrases and words. Edit these lists to change what gets rejected.
const banned = {
  ai_cliche: [
    "that's a bold move",
    "that's quite the",
    "that's a smart approach",
    "that's a wide range",
    'wide range of capabilities',
    'quite the',
    'smart approach to',
  ],
  sales_language: ['happy to discuss', 'would love to chat', "let's connect", 'feel free to reach out', 'let me know if'],
  sales_pitch: ['could save', 'would save', 'proactively notifying', 'this could help', 'might want to consider'],
  generic_praise: ['sounds like', 'looks like', "that's impressive", 'great work', 'i really enjoyed'],
  banned_word: ['exciting', 'passionate', 'innovative', 'disrupting'],
};

for (const [reason, phrases] of Object.entries(banned)) {
  const hit = phrases.find((phrase) => lower.includes(phrase));
  if (hit) return result('SKIP', 'skipped', `${reason}: ${hit}`);
}

return result(icebreaker, 'ok');
